// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a mock oracle that returns a fixed price at version 1
        address oracle = address(new MockOracle());

        // Initialize the product with the oracle
        IProduct.ProductInfo memory info;
        info.oracle = IOracleProvider(oracle);
        info.payoffDefinition.payoffType = PayoffDefinitionLib.PayoffType.LINEAR;
        info.payoffDefinition.payoffDirection = PayoffDefinitionLib.PayoffDirection.LONG;
        info.maintenance = UFixed18.wrap(0.1e18);
        info.fundingFee = UFixed18.wrap(0);
        info.makerFee = UFixed18.wrap(0);
        info.takerFee = UFixed18.wrap(0);
        info.positionFee = UFixed18.wrap(0);
        info.makerLimit = UFixed18.wrap(1000e18);
        info.utilizationCurve.minRate = PackedFixed18.wrap(0);
        info.utilizationCurve.maxRate = PackedFixed18.wrap(0);
        info.utilizationCurve.targetRate = PackedFixed18.wrap(0);
        info.utilizationCurve.targetUtilization = PackedUFixed18.wrap(0);
        c.initialize(info);

        // Call atVersion(1) on the reference - should return a version with price = 1000e18
        IOracleProvider.OracleVersion memory v = c.atVersion(1);
        // The reference oracle() returns the oracle address, so atVersion works
        assertTrue(v.price == Fixed18.wrap(1000e18), "Reference should have price 1000");
    }
}

interface IOracleProvider {
    struct OracleVersion {
        uint256 version;
        uint256 timestamp;
        Fixed18 price;
    }
    function sync() external returns (OracleVersion memory);
    function currentVersion() external view returns (OracleVersion memory);
    function atVersion(uint256) external view returns (OracleVersion memory);
}

contract MockOracle is IOracleProvider {
    function sync() external returns (OracleVersion memory) {
        return OracleVersion(1, block.timestamp, Fixed18.wrap(1000e18));
    }
    function currentVersion() external view returns (OracleVersion memory) {
        return OracleVersion(1, block.timestamp, Fixed18.wrap(1000e18));
    }
    function atVersion(uint256) external view returns (OracleVersion memory) {
        return OracleVersion(1, block.timestamp, Fixed18.wrap(1000e18));
    }
}

library Fixed18Lib {
    int256 private constant BASE = 1e18;
    function from(int256 a) internal pure returns (Fixed18) { return Fixed18.wrap(a * BASE); }
}

type Fixed18 is int256;
using Fixed18Lib for Fixed18 global;

type UFixed18 is uint256;

type PackedFixed18 is int128;
type PackedUFixed18 is uint128;

library PayoffDefinitionLib {
    enum PayoffType { LINEAR, INVERSE, DIGITAL, CLIQUE }
    enum PayoffDirection { LONG, SHORT }
}

struct PayoffDefinition {
    PayoffDefinitionLib.PayoffType payoffType;
    PayoffDefinitionLib.PayoffDirection payoffDirection;
    bytes30 data;
}

interface IProduct {
    struct ProductInfo {
        string name;
        string symbol;
        PayoffDefinition payoffDefinition;
        IOracleProvider oracle;
        UFixed18 maintenance;
        UFixed18 fundingFee;
        UFixed18 makerFee;
        UFixed18 takerFee;
        UFixed18 positionFee;
        UFixed18 makerLimit;
        JumpRateUtilizationCurve utilizationCurve;
    }
    function initialize(ProductInfo calldata) external;
    function oracle() external view returns (IOracleProvider);
    function atVersion(uint256) external view returns (IOracleProvider.OracleVersion memory);
}

struct JumpRateUtilizationCurve {
    PackedFixed18 minRate;
    PackedFixed18 maxRate;
    PackedFixed18 targetRate;
    PackedUFixed18 targetUtilization;
}

struct Accumulator {
    Fixed18 maker;
    Fixed18 taker;
}

