pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    // Mock oracle that returns price 1000e18 at version 1
    address oracle = address(new MockOracle());

    function setUp() public { 
        c = new C(); 

        // Build ProductInfo
        IProduct.ProductInfo memory info;
        info.name = "Test";
        info.symbol = "TST";
        // Create a valid PayoffDefinition (default PAYOFF_NONE = 0, IDENTITY direction = 0)
        info.payoffDefinition = PayoffDefinition({
            payoffType: PayoffDefinitionLib.PayoffType.PAYOFF_NONE,
            payoffDirection: PayoffDefinitionLib.PayoffDirection.IDENTITY,
            data: bytes30(0)
        });
        info.oracle = IOracleProvider(oracle);
        info.maintenance = UFixed18.wrap(0.1e18);
        info.fundingFee = UFixed18.wrap(0);
        info.makerFee = UFixed18.wrap(0);
        info.takerFee = UFixed18.wrap(0);
        info.positionFee = UFixed18.wrap(0);
        info.makerLimit = UFixed18.wrap(1000000e18);

        // Use a valid JumpRateUtilizationCurve (minRate=0, targetRate=0, maxRate=0, targetUtilization=0.8e18)
        JumpRateUtilizationCurve memory curve;
        curve.minRate = PackedFixed18.wrap(0);
        curve.maxRate = PackedFixed18.wrap(0);
        curve.targetRate = PackedFixed18.wrap(0);
        curve.targetUtilization = PackedUFixed18.wrap(0.8e18);
        info.utilizationCurve = curve;

        // Initialize through controller (we use vm.prank to simulate controller)
        // Deploy a minimal controller first
        // Actually we directly call c.initialize(msg.sender) via prank
        vm.prank(address(new MockController()));
        c.initialize(info);
    }

    function testRegression_property() public {
        // Call atVersion(1) - this will trigger oracle() internally
        IOracleProvider.OracleVersion memory v = c.atVersion(1);

        // In the reference, price should be 1000e18 (from the mock)
        // In the buggy version, price will be 0 (address(0) returns empty)
        assertTrue(v.price == Fixed18.wrap(1000e18), "Price should be 1000e18");
    }
}

// Helper mock oracle contract
contract MockOracle is IOracleProvider {
    function sync() external returns (OracleVersion memory) {
        OracleVersion memory v;
        v.version = 1;
        v.timestamp = block.timestamp;
        v.price = Fixed18.wrap(1000e18);
        return v;
    }

    function currentVersion() external view returns (OracleVersion memory) {
        OracleVersion memory v;
        v.version = 1;
        v.timestamp = block.timestamp;
        v.price = Fixed18.wrap(1000e18);
        return v;
    }

    function atVersion(uint256 oracleVersion) external view returns (OracleVersion memory) {
        require(oracleVersion == 1, "Only version 1");
        OracleVersion memory v;
        v.version = 1;
        v.timestamp = block.timestamp;
        v.price = Fixed18.wrap(1000e18);
        return v;
    }
}

